window.DEFAULT_CARDS = [{"id": "c0001", "name": "接地極付コンセント", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "接地極が付いたコンセント。接地が必要な接地極付プラグの差込口に用います。洗濯機や電子レンジのコンセントには接地極付きコンセントもしくは接地極付接地端子付コンセントを使用することが規定されています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0002", "name": "接地極付接地端子付コンセント", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "接地線を接続する接地端子と接地極の両方を持つコンセントです。洗濯機や電子レンジのコンセントには接地極付きコンセントもしくは接地極付接地端子付コンセントを使用することが規定されています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0003", "name": "接地端子付コンセント", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "接地線を接続するための接地端子が付いたコンセントです。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0004", "name": "防雨形コンセント", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "屋外の雨水がかかる場所に取り付けるコンセントです。雨水がかからないようにフードがついています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0005", "name": "抜け止め形コンセント", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "受け口が「こ」の字形のコンセントです。プラグを差し込んでから右にひねると引っ張っても抜けにくくなります。主に天井付コンセントなどで見かけることがあります。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0006", "name": "接地極付コンセント（三相200V）", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "三相200V用の接地極付コンセント。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0007", "name": "確認表示灯内蔵スイッチ", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "スイッチが「入」の状態になると表示灯が点灯します。そのため、スイッチが入っていること=機械が動作していることを容易に確認することができます。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0008", "name": "位置表示灯内蔵スイッチ", "category": "配線図記号", "tags": [], "difficulty": 2, "description": "スイッチが「切」の状態になると表示灯が点灯します。そのため、照明が点灯していない暗闇でも位置表示灯内蔵スイッチの表示灯が点灯し、スイッチの位置を容易に確認することができます。別名「ほたるスイッチ」とも呼ばれています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0009", "name": "3路スイッチ", "category": "配線図記号", "tags": ["複線図"], "difficulty": 2, "description": "二ヶ所から照明の点滅を行うためのスイッチ。外観はなにも特徴が無く4路スイッチと似ています。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}, {"id": "c0010", "name": "4路スイッチ", "category": "配線図記号", "tags": ["複線図"], "difficulty": 2, "description": "3ヶ所以上の場所から照明の点滅を行うためのスイッチで3路スイッチと組み合わせて使用します。基本的に4路スイッチ単独で使用することはありません。外観はなにも表示がなく3路スイッチと似ています。第二種電気工事士技能試験でも登場します。", "symbolImage": true, "photoImage": true, "createdAt": "2026-08-15T00:00:00.000Z", "updatedAt": "2026-08-15T00:00:00.000Z"}];
